"use client";

// The 20-channel study (Nov 2026): 90 strategies coded from 20 YouTube channels, in four sections (Indian equity
// intraday, Indian options, crypto, gold). Rules, evidence, assumptions and backtests come from ./channels20Data.ts
// (generated by backend/research/youtube_channels20_2026_11/zc_export.py); the paper status of each book comes live from
// the desk (premium-paper-service/segments.py). Paper only: simulated orders on real market data, nothing real.
import { useMemo, useState } from "react";
import GlassPanel from "../../components/GlassPanel";
import { CH20, CH20_BLOCKED, CH20_CHANNELS, CH20_DUPLICATES, CH20_META, CH20_SKIPPED, type Ch20Book, type Ch20Strategy } from "./channels20Data";
import { istTime, num, pct, rupees, tone } from "./format";
import type { Account, Summary } from "./PaperDesk";
import { SEG_PLACE, type SegFocus, type SegId } from "./Segments";
import type { StrategyRankBoard } from "../../lib/api";
import { RankNote, rankOnClient, rankTitle, sortByRank } from "../../components/StrategyRank";
import { ACCOUNT_RANK_NOTE, PREMIUM_RANK_FACTORS, accountRankRow } from "./rank";

type BookRow = { mkt: string; market: string; segment?: string; state: string; reason: string; trades: number; closed: number; open: number; pnl: number;
  unrealised: number; signal?: { last_t: number | null; today: boolean | null; taken: boolean | null; why: string | null; n_today: number | null } | null };
type Feed = { state: string; reason: string; source?: string; instrument?: string; last_t?: number | null };
type Status = { books?: Record<string, BookRow[]>; feeds?: Record<string, Feed>; yc2_start?: string };

const SECTIONS = [
  { id: "india_intraday", label: "Indian Market — Equity Intraday", has: (s: string) => s === "india_intraday",
    note: "Nifty and Bank Nifty intraday (futures-style, one lot of 65 / 30), NSE cash stocks on 5- and 15-minute bars, NSE swing and daily rules. Angel One data through the app's backend; NSE sessions 09:15-15:30 IST." },
  { id: "india_options", label: "Indian Market — Options", has: (s: string) => s === "india_options",
    note: "Strategies the videos trade with options. The desk has no intraday option premiums, so each trades the index (or the stock) signal as a proxy and says so; the option-premium strategies themselves are blocked below." },
  { id: "crypto", label: "Crypto", has: (s: string) => s === "crypto" || s === "crypto_gold",
    note: "Bitcoin and ether on Delta Exchange India's perpetuals (BTCUSD 0.001 BTC, ETHUSD 0.01 ETH contracts), 1-minute candles read every 2 minutes, Delta's taker fee and slippage charged." },
  { id: "gold", label: "Gold", has: (s: string) => s === "gold" || s === "crypto_gold",
    note: "Gold on Delta Exchange India's XAUTUSD perpetual at its 0.001 contract size, following the gold market's week (closed Friday 17:00 to Sunday 17:00 New York), as tested." },
] as const;
type SectionId = (typeof SECTIONS)[number]["id"];
/** The desk's name for this study: its accounts' `source`, which the market tabs filter on. */
const STUDY = "youtube_channels20";
const isSeg = (s?: string): s is SegId => !!s && s in SEG_PLACE;
type OpenFn = (f: Omit<SegFocus, "at">) => void;

const STATE: Record<string, { label: string; cls: string }> = {
  "in trade": { label: "Running — in a trade", cls: "c20-run" }, running: { label: "Running", cls: "c20-run" },
  live: { label: "Running", cls: "c20-run" }, armed: { label: "Armed", cls: "c20-idle" }, waiting: { label: "Ready", cls: "c20-idle" },
  closed: { label: "Armed", cls: "c20-idle" }, stale: { label: "Paused", cls: "c20-bad" }, "no data": { label: "Paused", cls: "c20-bad" },
  error: { label: "Paused", cls: "c20-bad" },
};
const RANK: Record<string, number> = { "in trade": 0, running: 1, live: 1, armed: 2, closed: 2, waiting: 3, stale: 4, "no data": 4, error: 5 };

function strategyState(rows: BookRow[] | undefined, started: boolean): { label: string; cls: string } {
  if (!started) return { label: "Ready", cls: "c20-idle" };
  if (!rows || !rows.length) return { label: "Validating", cls: "c20-idle" };
  const best = [...rows].sort((a, b) => (RANK[a.state] ?? 9) - (RANK[b.state] ?? 9))[0];
  return STATE[best.state] ?? { label: best.state, cls: "c20-idle" };
}

const r3 = (x: number | null) => (x == null ? "—" : `${x > 0 ? "+" : x < 0 ? "−" : ""}${Math.abs(x).toFixed(3)}R`);

function BacktestTable({ books }: { books: Ch20Book[] }) {
  return (
    <table className="c20-bt">
      <thead>
        <tr><th>Market</th><th>Trades</th><th>Win</th><th>Net / trade</th><th>Before costs</th><th>Total</th><th>PF</th><th>Max DD</th><th>t</th></tr>
      </thead>
      <tbody>
        {books.map((b) => (
          <tr key={b.book}>
            <td>{b.market}{b.window ? <div className="c20-dim">{b.window[0]} → {b.window[1]}</div> : null}</td>
            <td>{b.n}</td>
            <td>{b.winRate == null ? "—" : `${Math.round(100 * b.winRate)}%`}</td>
            <td className={tone(b.meanR)}>{r3(b.meanR)}</td>
            <td className={tone(b.grossR)}>{r3(b.grossR)}</td>
            <td className={tone(b.totalR)}>{num(b.totalR)}R</td>
            <td>{b.pf ?? "—"}</td>
            <td>{b.maxDdR == null ? "—" : `${b.maxDdR}R`}</td>
            <td>{b.t ?? "—"}</td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

function Card({ s, account, rows, feeds, started, startAt, board, onOpen }: { s: Ch20Strategy; account?: Account; rows?: BookRow[]; feeds: Record<string, Feed>;
  board?: StrategyRankBoard; onOpen?: OpenFn;
  started: boolean; startAt: string | null }) {
  const st = strategyState(rows, started);
  const verdicts = Array.from(new Set(s.books.map((b) => b.verdict)));
  const open = rows?.reduce((n, r) => n + (r.open || 0), 0) ?? 0;
  const unreal = rows?.reduce((n, r) => n + (r.unrealised || 0), 0) ?? 0;
  const sig = rows?.map((r) => ({ ...r.signal, mkt: r.market })).filter((x) => x.last_t).sort((a, b) => (b.last_t ?? 0) - (a.last_t ?? 0))[0];
  const traded = account ? account.closed + account.open : 0;
  return (
    <div className="ps-card c20-card">
      <div className="ps-card-top">
        <span className="ps-fam up">{s.id} · {s.version}</span>
        {board && (board.ranks[s.id]
          ? <span className="srank-cell c20-rank" title={rankTitle(board, board.ranks[s.id])} data-score={board.ranks[s.id].score.toFixed(1)}>Rank {board.ranks[s.id].rank}</span>
          : <span className="c20-rank c20-dim" title={rankTitle(board, undefined)}>Not ranked yet</span>)}
        <span className={`c20-state ${st.cls}`}>{st.label}</span>
      </div>
      <div className="ps-card-name">{s.name}</div>
      <div className="c20-line">
        {s.books.map((b) => b.market).join(" · ")} · {s.timeframes.join(", ")} candles{s.overnight ? " · held overnight" : " · intraday"}
      </div>
      <div className="c20-line c20-dim">{s.books.map((b) => b.instrument).join(" · ")}</div>
      {s.proxy && <div className="c20-proxy">Option strategy in the video — {s.proxy}.</div>}
      <div className="c20-line">
        <a href={s.channelUrl} target="_blank" rel="noreferrer">{s.channel}</a>
        {" · videos: "}
        {s.videos.map((v, i) => (
          <span key={v}>{i ? ", " : ""}<a href={`https://youtu.be/${v}`} target="_blank" rel="noreferrer">{v}</a></span>
        ))}
      </div>
      <div className="c20-tags">
        <span className={`c20-tag ${s.readiness === "ready" ? "ok" : "warn"}`}>{s.readiness === "ready" ? "Rules explicit" : "Documented assumptions"}</span>
        <span className={`c20-tag ${s.lookahead ? "ok" : "bad"}`}>{s.lookahead ? "Look-ahead check passed" : "Look-ahead check failed"}</span>
        {verdicts.map((v) => <span key={v} className={`c20-tag ${v.startsWith("Positive") ? "warn" : v.startsWith("Not supported") ? "bad" : ""}`}>Backtest: {v}</span>)}
      </div>

      <details className="c20-sec">
        <summary>Rules: entry, exit, stop, target, risk ({s.rules.length})</summary>
        <ul className="c20-rules">
          {s.rules.map(([label, text], i) => <li key={i}>{label ? <b>{label}: </b> : null}{text}</li>)}
        </ul>
        <p className="c20-dim">[E] stated in the video (with the time) · [I] inferred from the video · [A] a research assumption that makes the rule testable.</p>
      </details>
      <details className="c20-sec">
        <summary>Backtest after costs</summary>
        <BacktestTable books={s.books} />
        <p className="c20-dim">In-sample: these windows include the period the videos were made in. A positive number is not evidence of an edge.</p>
      </details>

      <div className="c20-paper">
        <div><span className="ps-stat-label">Paper capital</span> ₹10,00,000 · {s.books.map((b) => `${b.market}: ${b.risk}`).join(" · ")}</div>
        <div><span className="ps-stat-label">Activation</span> {startAt ? istTime(Date.parse(startAt) / 1000) + " IST" : "—"} · simulated orders only, entries on fresh signals after it</div>
        {(rows ?? []).map((r) => {
          const f = feeds[r.mkt === "XAUTUSD" ? "XAUUSD" : r.mkt.startsWith("NSE") && r.mkt !== "NSED" ? "NSE" : r.mkt];
          const seg = isSeg(r.segment) ? r.segment : null;
          return (
            <div key={r.mkt} className="c20-row">
              <span className={`c20-state ${(STATE[r.state] ?? { cls: "c20-idle" }).cls}`}>{(STATE[r.state] ?? { label: r.state }).label}</span>
              <span>
                <b>{r.market}</b> — {r.reason}{f ? <span className="c20-dim"> · data: {f.state}{f.source ? ` (${f.source})` : ""}</span> : null}
                {onOpen && seg ? (
                  <button className="c20-open" onClick={() => onOpen({ seg, study: STUDY, book: `${s.id}|${r.mkt}` })}>
                    {`Open in ${SEG_PLACE[seg].label} →`}
                  </button>
                ) : null}
              </span>
            </div>
          );
        })}
        <div><span className="ps-stat-label">Latest signal</span> {sig ? `${istTime(sig.last_t)} IST on ${sig.mkt}${sig.taken === false ? ` — not taken: ${sig.why ?? "see the rules"}` : sig.taken ? " — taken" : ""}` : "none since activation"}</div>
        <div><span className="ps-stat-label">Open positions</span> {open ? `${open} · unrealised ${rupees(unreal)}` : "none"}</div>
        <div>
          <span className="ps-stat-label">Paper performance</span>{" "}
          {account ? (traded ? <>{rupees(account.equity)} <b className={tone(account.return_pct)}>{pct(account.return_pct)}</b> · {account.closed} closed, {account.wins} won{account.profit_factor != null ? ` · PF ${account.profit_factor}` : ""}</> : <>{rupees(account.equity)} · no trades yet</>) : "account not on the desk yet"}
        </div>
      </div>
    </div>
  );
}

export default function Channels20({ summary, error, onOpen }: { summary: Summary | null; error: string | null; onOpen?: OpenFn }) {
  const [sec, setSec] = useState<SectionId>("india_intraday");
  const [q, setQ] = useState("");
  const status = (summary?.status ?? {}) as Status;
  const byId = useMemo(() => Object.fromEntries((summary?.accounts ?? []).map((a) => [a.id, a])) as Record<string, Account>, [summary]);
  const startAt = status.yc2_start ?? null;
  const started = startAt ? Date.now() >= Date.parse(startAt) : false;
  const S = SECTIONS.find((x) => x.id === sec)!;
  const ql = q.trim().toLowerCase();
  // Ranked within the section, on each strategy's paper account (rank.ts); the search only filters the cards.
  const board = useMemo(() => rankOnClient(
    CH20.filter((s) => S.has(s.section)).map((s) => (byId[s.id] ? accountRankRow(byId[s.id]) : { id: s.id, trades: 0, values: {} })),
    PREMIUM_RANK_FACTORS, { desk: `premium-c20-${sec}`, basisNote: ACCOUNT_RANK_NOTE }), [S, byId, sec]);
  const list = sortByRank(CH20.filter((s) => S.has(s.section) && (!ql || `${s.id} ${s.name} ${s.channel}`.toLowerCase().includes(ql))),
    board, (s) => s.id);
  const blocked = CH20_BLOCKED.filter((b) => S.has(b.section));
  const m = CH20_META;
  // Where this section's strategies paper trade: every book is a row of one market tab (Indian Market has three
  // sub-tabs). A button's count is what that tab shows with this study's filter on: all 20-channel rows there.
  const inSec = CH20.filter((s) => S.has(s.section));
  const onDesk = inSec.filter((s) => byId[s.id]).length;
  const here = new Set<SegId>();
  inSec.forEach((s) => (status.books?.[s.id] ?? []).forEach((b) => { if (isSeg(b.segment)) here.add(b.segment); }));
  const rowsIn: Partial<Record<SegId, number>> = {};
  (summary?.accounts ?? []).forEach((a) => {
    if (a.source === STUDY) (status.books?.[a.id] ?? []).forEach((b) => { if (isSeg(b.segment)) rowsIn[b.segment] = (rowsIn[b.segment] ?? 0) + 1; });
  });
  const places = (Object.keys(SEG_PLACE) as SegId[]).filter((g) => here.has(g));
  return (
    <>
      <GlassPanel title="20 more YouTube channels — research to paper trading" note={`${m.coded} strategies coded · ${m.blocked} blocked · paper only`}>
        <p className="c20-intro">
          {m.discovered} channels were found by search; the {m.covered_before} channels of the earlier studies were removed and {m.shortlisted} were
          shortlisted by how much of their content is strategy videos. {m.selected} were chosen for clear, complete rules shown on charts across
          Indian equity, Indian options, crypto and gold. {m.videos_analysed} videos were analysed from their transcripts ({m.whisper} through Whisper),
          giving {m.coded} coded strategies (version v1 each), {m.blocked} blocked ones (incomplete rules or data the desk does not have),{" "}
          {m.duplicates} duplicates of the existing library and {m.merged} second sources merged into a strategy. All {m.lookahead_ok} coded strategies
          passed the truncation (look-ahead) and fill checks. Backtests after costs: {m.books_positive} of {m.books} strategy-market books are
          positive, all in-sample. {m.playlist_videos_queued} playlist videos outside the channels' upload lists are queued, not analysed.
        </p>
        {error && <p className="c20-err">The paper desk could not be read: {error}. The research below is static and still shown.</p>}
      </GlassPanel>

      <div className="ps-chips c20-secs">
        {SECTIONS.map((x) => (
          <button key={x.id} className={`ps-chip${sec === x.id ? " on" : ""}`} onClick={() => setSec(x.id)}>
            {x.label} · {CH20.filter((s) => x.has(s.section)).length}
          </button>
        ))}
        <input className="c20-q" placeholder="Search id, name, channel" value={q} onChange={(e) => setQ(e.target.value)} />
      </div>
      <p className="c20-note">{S.note}</p>
      {summary && (
        <div className="c20-where">
          <span className="ps-stat-label">Paper trading</span>
          <span>
            {`${onDesk === inSec.length ? `All ${inSec.length}` : `${onDesk} of these ${inSec.length}`} paper trade their own ₹10,00,000 account on real market data${places.length ? ". Each market's rows are in its tab:" : "; no book has reached the desk yet."}`}
          </span>
          {places.map((g) => (
            <button key={g} className="ps-chip" onClick={() => onOpen?.({ seg: g, study: STUDY })}>{`${SEG_PLACE[g].label} · ${rowsIn[g] ?? 0} →`}</button>
          ))}
        </div>
      )}
      <RankNote board={board} />
      <div className="ps-cards c20-cards">
        {list.map((s) => (
          <Card key={s.id} s={s} account={byId[s.id]} rows={status.books?.[s.id]} feeds={status.feeds ?? {}} started={started} startAt={startAt} board={board}
            onOpen={onOpen} />
        ))}
      </div>
      {blocked.length > 0 && (
        <GlassPanel title={`Blocked in ${S.label}`} note="no account: not forced into automated trading">
          <ul className="c20-blocked">
            {blocked.map((b) => (
              <li key={b.id}><b>{b.id} {b.name}</b> ({b.channel}; {b.videos.map((v) => <a key={v} href={`https://youtu.be/${v}`} target="_blank" rel="noreferrer">{v}</a>)}) — {b.reason}</li>
            ))}
          </ul>
        </GlassPanel>
      )}
      <details className="c20-sec c20-wide">
        <summary>The 20 channels, and why ({CH20_CHANNELS.length}); shortlisted but skipped ({CH20_SKIPPED.length}); duplicates ({CH20_DUPLICATES.length})</summary>
        <table className="c20-bt">
          <thead><tr><th>Channel</th><th>Markets</th><th>Strategies taught</th><th>Language</th><th>Why chosen</th><th>Videos</th><th>Coded / blocked</th></tr></thead>
          <tbody>
            {CH20_CHANNELS.map((c) => (
              <tr key={c.id}>
                <td><a href={c.url} target="_blank" rel="noreferrer">{c.name}</a><div className="c20-dim">{c.id}</div></td>
                <td>{c.markets}</td><td>{c.coverage}</td><td>{c.language}</td><td>{c.why}</td>
                <td>{c.selected} of {c.uploads} uploads</td><td>{c.coded} / {c.blocked}</td>
              </tr>
            ))}
          </tbody>
        </table>
        <ul className="c20-blocked">
          {CH20_SKIPPED.map((s) => <li key={s.id}><b>{s.name}</b> — skipped: {s.reason}</li>)}
          {CH20_DUPLICATES.map((d) => <li key={d.video}><b>{d.video}</b> ({d.channel}) — {d.what}: duplicate of {d.duplicateOf}</li>)}
        </ul>
      </details>
      {/* global: the cards are drawn by <Card>, a child component, which scoped styles never reach; every
          selector here is c20-prefixed, so nothing outside this tab is touched. */}
      <style jsx global>{`
        .c20-intro { font-size: 13px; line-height: 1.6; color: var(--text-muted); margin: 0; }
        .c20-err { color: #f87171; font-size: 12.5px; }
        .c20-secs { margin: 14px 0 6px; align-items: center; }
        .c20-q { margin-left: auto; min-width: 200px; padding: 6px 10px; border-radius: 8px; border: 1px solid var(--border, #333); background: transparent; color: inherit; font-size: 12.5px; }
        .c20-note { font-size: 12.5px; color: var(--text-muted); margin: 4px 0 12px; line-height: 1.5; }
        .c20-cards { align-items: start; }
        .c20-line { font-size: 12.5px; line-height: 1.5; margin-top: 4px; overflow-wrap: anywhere; }
        .c20-dim { color: var(--text-muted); font-size: 11.5px; }
        .c20-proxy { font-size: 12px; margin-top: 6px; padding: 6px 8px; border-radius: 6px; background: rgba(234, 179, 8, 0.1); color: #eab308; }
        .c20-tags { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 8px; }
        .c20-tag { font-size: 11px; padding: 2px 8px; border-radius: 999px; border: 1px solid rgba(148, 163, 184, 0.35); color: var(--text-muted); }
        .c20-tag.ok { border-color: rgba(34, 197, 94, 0.45); color: #22c55e; }
        .c20-tag.warn { border-color: rgba(234, 179, 8, 0.45); color: #eab308; }
        .c20-tag.bad { border-color: rgba(248, 113, 113, 0.45); color: #f87171; }
        .c20-state { font-size: 11px; padding: 2px 8px; border-radius: 999px; white-space: nowrap; }
        .c20-run { background: rgba(34, 197, 94, 0.15); color: #22c55e; }
        .c20-idle { background: rgba(148, 163, 184, 0.15); color: var(--text-muted); }
        .c20-bad { background: rgba(248, 113, 113, 0.15); color: #f87171; }
        .c20-sec { margin-top: 10px; font-size: 12.5px; }
        .c20-sec summary { cursor: pointer; font-weight: 600; }
        .c20-wide { margin: 16px 0; }
        .c20-rules { margin: 8px 0; padding-left: 18px; line-height: 1.55; }
        .c20-rules li { margin-bottom: 4px; overflow-wrap: anywhere; }
        .c20-bt { width: 100%; border-collapse: collapse; font-size: 11.5px; margin-top: 8px; display: block; overflow-x: auto; }
        .c20-bt th, .c20-bt td { padding: 4px 6px; border-bottom: 1px solid rgba(148, 163, 184, 0.15); text-align: left; vertical-align: top; }
        .c20-paper { margin-top: 12px; padding-top: 10px; border-top: 1px solid rgba(148, 163, 184, 0.2); font-size: 12px; line-height: 1.6; display: grid; gap: 4px; }
        .c20-row { display: flex; gap: 8px; align-items: flex-start; }
        .c20-where { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin: 0 0 12px; font-size: 12.5px; line-height: 1.5;
                     color: var(--text-muted); }
        .c20-where .ps-chip { font-weight: 700; }
        .c20-open { margin-left: 8px; padding: 0; border: 0; background: none; color: var(--purple); font: inherit; font-size: 11.5px;
                    font-weight: 700; cursor: pointer; text-decoration: underline; text-underline-offset: 2px; }
        .c20-blocked { font-size: 12.5px; line-height: 1.6; padding-left: 18px; }
        .c20-blocked a { margin-right: 4px; }
      `}</style>
    </>
  );
}
